values.content:
Write a job description.

Role: {{ $json.jobTitle }}
Department: {{ $json.department }}
Seniority: {{ $json.seniorityLevel }}
Work type: {{ $json.workType }}{{ $json.location ? ' — ' + $json.location : '' }}
Company stage: {{ $json.companyStage || 'not specified' }}
Tone: {{ $json.tone }}
Avoid biased language: {{ $json.avoidBiasedLanguage }}

Company description:
{{ $json.companyDescription }}

Team context (what team/org this reports into):
{{ $json.teamContext || 'not provided' }}

Core responsibilities:
{{ $json.coreResponsibilities.map((r,i) => `${i+1}. ${r}`).join('\n') || 'not specified — infer from role title and department' }}

Must-have skills/requirements:
{{ $json.mustHaveSkills.join(', ') || 'not specified — infer from role' }}

Nice-to-have skills:
{{ $json.niceToHaveSkills.join(', ') || 'none specified' }}

Salary range: {{ $json.salaryRange || 'not specified' }}
Benefits: {{ $json.benefits.join(', ') || 'not specified' }}

Return this JSON:
{
  "job_title_display": "final job title — clean, searchable, no internal codes",
  "headline": "one-line hook that makes a strong candidate lean forward — what makes this role genuinely interesting",
  "sections": {
    "about_the_company": "2-3 sentences. What does the company do, who are their customers, what stage are they at. Honest and specific — not marketing copy.",
    "about_the_role": "2-3 paragraphs. What will this person actually spend their time doing? What problems will they solve? What does success look like at 6 months?",
    "what_youll_do": ["5-8 specific responsibilities — use action verbs, be concrete, avoid vague phrases like 'support the team'"],
    "what_were_looking_for": ["5-7 must-have requirements — specific and honest. No inflated requirements."],
    "bonus_points": ["3-5 genuinely nice-to-have skills — not required"],
    "what_we_offer": ["5-7 benefits/perks — include salary if provided, include meaningful ones not just 'competitive salary'"],
    "honest_challenges": "1-2 sentences about what's genuinely hard about this role or this stage of the company — candidates appreciate honesty and it filters for the right people"
  },
  "full_jd_text": "the complete job description as a single formatted string with section headers and line breaks — ready to paste into a job board",
  "bias_flags": ["if avoid_biased_language is true: any language in the JD that could discourage qualified candidates — empty if clean"],
  "searchability_notes": "whether the job title and keywords will perform well on job boards — any suggestions",
  "interview_signal": "based on this JD, what's the single most important thing to assess in first-round interviews"
}

parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let jd;
try { jd = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
jd._meta = { jobTitle: input.jobTitle, department: input.department, seniorityLevel: input.seniorityLevel, workType: input.workType, location: input.location, replyEmail: input.replyEmail };
return [{ json: jd }];

const j = $input.first().json;
const m = j._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const s = j.sections || {};
const responsibilities = (s.what_youll_do||[]).map(r => `<li style="font-size:14px;margin-bottom:8px;line-height:1.55">${esc(r)}</li>`).join('');
const requirements = (s.what_were_looking_for||[]).map(r => `<li style="font-size:14px;margin-bottom:8px;line-height:1.55">${esc(r)}</li>`).join('');
const bonus = (s.bonus_points||[]).map(b => `<li style="font-size:14px;margin-bottom:7px;line-height:1.55;color:#4b5563">${esc(b)}</li>`).join('');
const offers = (s.what_we_offer||[]).map(o => `<div style="font-size:14px;padding:6px 0;border-bottom:1px solid #f0fdf4">✓ ${esc(o)}</div>`).join('');
const biasFlags = (j.bias_flags||[]).map(f => `<li style="font-size:13px;margin-bottom:5px;color:#7f1d1d">${esc(f)}</li>`).join('');

const workTypeColors = {remote:'#16a34a', hybrid:'#2563eb', onsite:'#d97706'};
const wtColor = workTypeColors[m.workType] || '#6b7280';
const levelLabel = m.seniorityLevel.replace(/_/g,' ').replace(/ \w/g, c => c.toUpperCase());

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f9fafb;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111">
<div style="max-width:680px;margin:0 auto">
  <div style="background:#1e293b;color:#fff;padding:22px 28px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#64748b;margin-bottom:5px">${esc(m.department)} · ${esc(levelLabel)}</div>
    <div style="font-size:21px;font-weight:700">${esc(j.job_title_display||m.jobTitle)}</div>
    <div style="display:flex;gap:8px;margin-top:8px;flex-wrap:wrap">
      <span style="background:${wtColor}33;color:${wtColor};font-size:12px;font-weight:600;padding:3px 10px;border-radius:10px">${esc(m.workType)}</span>
      ${m.location ? `<span style="background:#f1f5f9;color:#475569;font-size:12px;padding:3px 10px;border-radius:10px">${esc(m.location)}</span>` : ''}
    </div>
    <div style="font-size:14px;color:#94a3b8;margin-top:10px;font-style:italic">${esc(j.headline)}</div>
  </div>
  <div style="background:#fff;padding:20px 28px;border:1px solid #e5e7eb;border-top:none">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">About the company</div>
    <p style="font-size:14px;line-height:1.75;color:#374151;margin:0">${esc(s.about_the_company)}</p>
  </div>
  <div style="background:#fff;padding:20px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">About the role</div>
    <div style="font-size:14px;line-height:1.8;color:#374151;white-space:pre-line">${esc(s.about_the_role)}</div>
  </div>
  ${responsibilities ? `<div style="background:#fff;padding:20px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:10px">What you'll do</div>
    <ul style="padding-left:18px;margin:0">${responsibilities}</ul>
  </div>` : ''}
  ${requirements ? `<div style="background:#fff;padding:20px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:10px">What we're looking for</div>
    <ul style="padding-left:18px;margin:0">${requirements}</ul>
  </div>` : ''}
  ${bonus ? `<div style="background:#fff;padding:20px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:10px">Bonus points</div>
    <ul style="padding-left:18px;margin:0">${bonus}</ul>
  </div>` : ''}
  ${s.honest_challenges ? `<div style="background:#fffbeb;padding:14px 28px;border:1px solid #fde68a">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#92400e;margin-bottom:6px">Honest about the challenges</div>
    <p style="font-size:14px;color:#78350f;line-height:1.65;margin:0">${esc(s.honest_challenges)}</p>
  </div>` : ''}
  ${offers ? `<div style="background:#f0fdf4;padding:16px 28px;border:1px solid #bbf7d0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#15803d;margin-bottom:8px">What we offer</div>
    ${offers}
  </div>` : ''}
  ${biasFlags ? `<div style="background:#fef2f2;padding:14px 28px;border:1px solid #fecaca">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#b91c1c;margin-bottom:7px">Potential bias flags — review before posting</div>
    <ul style="padding-left:18px;margin:0">${biasFlags}</ul>
  </div>` : ''}
  <div style="background:#fff;padding:14px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:5px">Interview signal</div>
    <div style="font-size:14px;color:#374151;line-height:1.6">${esc(j.interview_signal)}</div>
    ${j.searchability_notes ? `<div style="font-size:13px;color:#6b7280;margin-top:8px;background:#f9fafb;padding:8px 12px;border-radius:4px">${esc(j.searchability_notes)}</div>` : ''}
  </div>
  <div style="background:#1e293b;color:#475569;font-size:11px;padding:12px 28px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    JD Writer · ${esc(j.job_title_display||m.jobTitle)} · ${new Date().toLocaleDateString()}
  </div>
</div></body></html>`;

return [{ json: { html, replyEmail: m.replyEmail, jobTitle: j.job_title_display||m.jobTitle, department: m.department, jd: j } }];
